#include "gameos/gui/WindowManager.hpp"
#include <algorithm>
namespace gameos::gui{std::uint32_t WindowManager::create(std::string t,Rect r){auto id=nextId_++;windows_.push_back({id,std::move(t),r,true,std::make_shared<Scene>()});return id;}bool WindowManager::close(std::uint32_t id){auto i=std::remove_if(windows_.begin(),windows_.end(),[&](auto&w){return w.id==id;});if(i==windows_.end())return false;windows_.erase(i,windows_.end());return true;}Window*WindowManager::find(std::uint32_t id){for(auto&w:windows_)if(w.id==id)return&w;return nullptr;}void WindowManager::update(double d){for(auto&w:windows_)if(w.visible&&w.scene)w.scene->update(d);}void WindowManager::draw(Canvas&c)const{for(auto&w:windows_)if(w.visible&&w.scene)w.scene->draw(c);}bool WindowManager::dispatch(Event e){for(auto i=windows_.rbegin();i!=windows_.rend();++i)if(i->visible&&i->scene&&i->scene->dispatch(e))return true;return false;}}
